<template>
  <div class="tm-merchant-workspace">
    <template v-if="view === 'apply'"><div class="tm-heading"><h1>让好生意，在这里发生</h1><p>商户入驻资料会先保存为本次会话草稿。</p></div><div class="tm-merchant-steps tm-panel"><span v-for="(label,index) in steps" :key="label" :class="{ active: step === index }">{{ String(index+1).padStart(2,'0') }} {{ label }}</span></div><div class="tm-merchant-columns"><form class="tm-panel tm-merchant-form" @submit.prevent="nextStep"><h2>{{ ['填写基础信息','经营资质','店铺设置','核对申请'][step] }}</h2><template v-if="step===0"><div class="tm-tabs"><button class="tm-tab" :class="{ 'is-active': application.kind !== 'personal' }" type="button" @click="application.kind='business'">企业商家</button><button class="tm-tab" :class="{ 'is-active': application.kind === 'personal' }" type="button" @click="application.kind='personal'">个人服务商</button></div><label class="tm-field"><span>店铺名称</span><input v-model.trim="application.name" class="tm-input" required placeholder="输入店铺名称" /></label><label class="tm-field"><span>主营类目</span><select v-model="application.category" class="tm-select" required><option value="">请选择类目</option><option v-for="category in market.categories" :key="category.id" :value="category.id">{{ category.label }}</option></select></label><label class="tm-field"><span>联系人</span><input v-model.trim="application.contact" class="tm-input" required /></label><label class="tm-field"><span>联系电话</span><input v-model.trim="application.phone" class="tm-input" type="tel" required /></label></template><template v-else-if="step===1"><label class="tm-field"><span>{{ application.kind === 'personal' ? '身份证明说明' : '企业资质说明' }}</span><textarea v-model.trim="application.qualification" class="tm-textarea" required placeholder="填写资质信息及可验证的主体名称" /></label><label class="tm-field"><span>资质附件（仅显示文件名，不上传）</span><input class="tm-input" type="file" accept="image/*,.pdf" @change="selectLicense" /><small>{{ application.licenseName || '尚未选择文件' }}</small></label></template><template v-else-if="step===2"><label class="tm-field"><span>店铺简介</span><textarea v-model.trim="application.description" class="tm-textarea" required placeholder="介绍商品和服务" /></label><label class="tm-field"><span>预计交付方式</span><select v-model="application.delivery" class="tm-select" required><option value="">请选择交付方式</option><option>数字交付</option><option>实物配送</option><option>服务预约</option></select></label></template><template v-else><dl class="tm-merchant-review"><div><dt>店铺</dt><dd>{{ application.name }}</dd></div><div><dt>类目</dt><dd>{{ categoryName(application.category) }}</dd></div><div><dt>联系人</dt><dd>{{ application.contact }}</dd></div><div><dt>交付</dt><dd>{{ application.delivery }}</dd></div></dl><p>商户入驻审核接口尚未接入，当前资料未提交给平台。</p></template><div class="tm-merchant-form-actions"><button v-if="step>0" class="tm-button" type="button" @click="step--">上一步</button><button class="tm-button primary" type="submit">{{ step===3 ? '检查提交条件' : '保存并继续' }}</button></div></form><aside class="tm-panel tm-merchant-aside"><h2>入驻信息</h2><p>商品发布、订单履约与结算须经过平台审核和服务端权限校验。手续费、退款及结算周期遵循现有业务规则。</p></aside></div></template>
    <template v-else-if="view === 'overview'"><div class="tm-heading"><h1>经营概览</h1><p>商户经营数据将在专用接口接入后展示。</p></div><div class="tm-merchant-metrics"><div v-for="label in ['今日交易额','今日订单','待处理订单','可结算金额']" :key="label" class="tm-panel"><span>{{ label }}</span><strong>—</strong><small>等待服务端数据</small></div></div><section class="tm-panel tm-merchant-dashboard"><h2>经营工作台</h2><div class="tm-merchant-tools"><RouterLink class="tm-button" to="/token-market/merchant-products">管理商品</RouterLink><RouterLink class="tm-button" to="/token-market/merchant-products/new">发布商品</RouterLink><RouterLink class="tm-button" to="/token-market/merchant-orders">处理订单</RouterLink><RouterLink class="tm-button" to="/token-market/merchant-settlement">结算中心</RouterLink><RouterLink class="tm-button" to="/token-market/merchant-apply">入驻资料草稿</RouterLink></div></section><div class="tm-empty"><img src="/token-market/icons/chart.svg" alt="" /><h2>暂无经营趋势</h2><p>交易、库存与售后统计接口尚未接入，无法显示可信的经营数据。</p></div></template>
    <template v-else-if="view === 'products'"><div class="tm-heading"><h1>商品管理</h1><p>管理本地商品草稿。上架状态与库存须以商户服务端接口为准。</p></div><div class="tm-row tm-merchant-toolbar"><RouterLink class="tm-button primary" to="/token-market/merchant-products/new">+ 发布商品</RouterLink><input v-model="productSearch" class="tm-input" aria-label="搜索商品草稿" placeholder="搜索草稿名称或模型" /></div><div class="tm-tabs"><button v-for="tab in ['全部商品','本地草稿']" :key="tab" class="tm-tab" :class="{ 'is-active': productTab === tab }" @click="productTab=tab">{{ tab }}</button></div><div v-if="filteredDrafts.length" class="tm-panel tm-table-scroll"><table class="tm-data-table"><thead><tr><th>商品名称</th><th>模型 / Token 类型</th><th>模型 Token 数量</th><th>售价</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="entry in filteredDrafts" :key="entry.index"><td>{{ entry.draft.name }}</td><td>{{ entry.draft.modelId || '—' }}<small>{{ entry.draft.tokenTypes.join(' / ') || '—' }}</small></td><td>{{ entry.draft.modelTokenQuantity || '—' }}</td><td>{{ entry.draft.salePriceToken ? `${entry.draft.salePriceToken} T` : '—' }}</td><td>本地草稿</td><td><RouterLink class="tm-text-link" :to="`/token-market/merchant-products/new?edit=${entry.index}`">编辑</RouterLink></td></tr></tbody></table></div><div v-else class="tm-empty"><img src="/token-market/icons/shop.svg" alt="" /><h2>暂无商品草稿</h2><p>创建草稿后可在这里继续编辑；正式发布需要商户接口。</p><RouterLink class="tm-button primary" to="/token-market/merchant-products/new">新建商品草稿</RouterLink></div></template>
    <template v-else-if="view === 'publish'"><div class="tm-heading"><h1>{{ editIndex >= 0 ? '编辑商品草稿' : '发布商品' }}</h1><p>模型 Token 数量与钱包支付金额独立填写，报价与上架需服务端校验。</p></div><div class="tm-merchant-columns"><form class="tm-panel tm-merchant-form" @submit.prevent="saveProduct"><h2>商品信息</h2><label class="tm-field"><span>商品名称</span><input v-model.trim="product.name" class="tm-input" required /></label><label class="tm-field"><span>商品类目</span><select v-model="product.categoryId" class="tm-select" required><option value="">请选择类目</option><option v-for="category in market.categories" :key="category.id" :value="category.id">{{ category.label }}</option></select></label><label class="tm-field"><span>适用模型 ID</span><input v-model.trim="product.modelId" class="tm-input" required placeholder="填写服务端模型标识" /></label><fieldset class="tm-merchant-types"><legend>Token 类型（可多选）</legend><label v-for="type in tokenTypes" :key="type"><input v-model="product.tokenTypes" type="checkbox" :value="type" />{{ type }}</label></fieldset><label class="tm-field"><span>模型 Token 数量</span><input v-model.trim="product.modelTokenQuantity" class="tm-input" type="number" min="1" step="1" required inputmode="numeric" /></label><label class="tm-field"><span>组合说明</span><input v-model.trim="product.packageCombination" class="tm-input" placeholder="例如 Input + Output 组合" /></label><label class="tm-field"><span>钱包支付金额 T</span><input v-model.trim="product.salePriceToken" class="tm-input" type="number" min="0.01" step="0.01" required inputmode="decimal" /><small>售价与模型 Token 数量不是同一字段。</small></label><label class="tm-field"><span>商品说明</span><textarea v-model.trim="product.description" class="tm-textarea" required /></label><div class="tm-merchant-form-actions"><button class="tm-button primary" type="submit">保存本地草稿</button><button class="tm-button" type="button" @click="publishUnavailable=true">提交上架</button></div></form><aside class="tm-panel tm-merchant-aside"><h2>官方参考价格</h2><p>适用模型、Input / Output / Cache 类型、报价依据和更新时间必须由服务端返回。当前未提供参考价格接口，不能根据设计稿示例推导售价。</p><dl><div><dt>适用模型</dt><dd>等待服务端</dd></div><div><dt>类型</dt><dd>等待服务端</dd></div><div><dt>报价依据</dt><dd>等待服务端</dd></div><div><dt>更新时间</dt><dd>等待服务端</dd></div></dl></aside></div></template>
    <template v-else-if="view === 'orders'"><div class="tm-heading"><h1>商家订单</h1><p>处理待接单、待交付和售后请求。</p></div><div class="tm-tabs"><button v-for="tab in ['全部','待接单','待发货','配送中','已完成','售后']" :key="tab" class="tm-tab" :class="{ 'is-active': merchantOrderTab === tab }" @click="merchantOrderTab=tab">{{ tab }}</button></div><div class="tm-empty"><img src="/token-market/icons/orders.svg" alt="" /><h2>商家订单尚不可用</h2><p>当前只有买家订单列表接口，缺少商家订单、交付与售后处理接口。</p></div></template>
    <template v-else><div class="tm-heading"><h1>结算中心</h1><p>每一笔收入、费用和结算记录以服务端账本为准。</p></div><div class="tm-merchant-metrics"><div v-for="label in ['可结算金额','待结算金额','本月已结算']" :key="label" class="tm-panel"><span>{{ label }}</span><strong>—</strong><small>等待服务端账本</small></div></div><div class="tm-tabs"><button v-for="tab in ['结算记录','收支明细','费用明细']" :key="tab" class="tm-tab" :class="{ 'is-active': settlementTab === tab }" @click="settlementTab=tab">{{ tab }}</button></div><div class="tm-empty"><img src="/token-market/icons/wallet.svg" alt="" /><h2>暂无可核实的结算数据</h2><p>结算账户、手续费、周期和提现接口未接入；不会显示示例金额或提交申请。</p></div></template>
    <div v-if="publishUnavailable || submitUnavailable" class="tm-dialog-backdrop" @click.self="closeDialog"><div class="tm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="merchant-dialog-title"><h2 id="merchant-dialog-title">当前不能提交</h2><p>{{ publishUnavailable ? '商户权限、官方参考价、库存与商品上架接口尚未接入。可以继续保存本地草稿。' : '商户入驻申请与资质上传接口尚未接入。当前资料只在本次浏览器会话中保存。' }}</p><div class="tm-dialog-actions"><button class="tm-button primary" type="button" @click="closeDialog">知道了</button></div></div></div>
    <div v-if="toast" class="tm-toast" role="status">{{ toast }}</div>
  </div>
</template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { useMarketDraftStore, type MarketProductDraft } from '../experience'
import { useTokenMarketStore } from '../store'
const route = useRoute()
const router = useRouter()
const market = useTokenMarketStore()
const draft = useMarketDraftStore()
const view = computed(() => {
  if (route.path.endsWith('/merchant-apply')) return 'apply'
  if (route.path.endsWith('/merchant-products/new')) return 'publish'
  if (route.path.endsWith('/merchant-products')) return 'products'
  if (route.path.endsWith('/merchant-orders')) return 'orders'
  if (route.path.endsWith('/merchant-settlement')) return 'settlement'
  return 'overview'
})
const steps = ['基础信息', '经营资质', '店铺设置', '提交审核']
const step = ref(0)
const application = draft.data.merchantApplication
const tokenTypes = ['input', 'output', 'cache'] as const
const blankProduct = (): MarketProductDraft => ({ name: '', categoryId: 'ai_credit', modelId: '', tokenTypes: [], modelTokenQuantity: '', packageCombination: '', salePriceToken: '', description: '' })
const product = ref<MarketProductDraft>(blankProduct())
const editIndex = computed(() => Number.isInteger(Number(route.query.edit)) ? Number(route.query.edit) : -1)
const productSearch = ref('')
const productTab = ref('全部商品')
const merchantOrderTab = ref('全部')
const settlementTab = ref('结算记录')
const filteredDrafts = computed(() => draft.data.productDrafts.map((item,index) => ({ draft: item, index })).filter(item => !productSearch.value || item.draft.name.includes(productSearch.value) || item.draft.modelId.includes(productSearch.value)))
const publishUnavailable = ref(false)
const submitUnavailable = ref(false)
const toast = ref('')
function categoryName(id: string): string { return market.categories.find(item => item.id === id)?.label || '未选择' }
function selectLicense(event: Event): void { application.licenseName = (event.target as HTMLInputElement).files?.[0]?.name || '' }
function nextStep(): void { if (step.value < 3) step.value += 1; else submitUnavailable.value = true }
function closeDialog(): void { publishUnavailable.value = false; submitUnavailable.value = false }
function saveProduct(): void {
  if (!product.value.tokenTypes.length) { toast.value = '请至少选择一种 Token 类型'; return }
  if (editIndex.value >= 0) draft.updateProductDraft(editIndex.value, { ...product.value })
  else draft.saveProductDraft({ ...product.value })
  toast.value = '商品草稿已保存到当前浏览器，尚未发布'
  void router.push('/token-market/merchant-products')
}
watch(() => route.query.edit, () => { product.value = editIndex.value >= 0 ? structuredClone(draft.data.productDrafts[editIndex.value] || blankProduct()) : blankProduct() }, { immediate: true })
</script>
<style scoped>
.tm-merchant-steps{display:flex;justify-content:space-between;gap:12px;padding:24px;margin-bottom:24px}.tm-merchant-steps span{color:var(--tm-muted)}.tm-merchant-steps .active{color:var(--tm-cyan);font-weight:700}.tm-merchant-columns{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(300px,1fr);gap:24px}.tm-merchant-form,.tm-merchant-aside{align-self:start;padding:24px}.tm-merchant-form h2,.tm-merchant-aside h2{margin:0 0 18px}.tm-merchant-aside p{color:var(--tm-muted)}.tm-merchant-aside dl div,.tm-merchant-review div{display:flex;justify-content:space-between;gap:16px;padding:10px 0;border-bottom:1px solid var(--tm-border)}.tm-merchant-aside dt,.tm-merchant-review dt{color:var(--tm-muted)}.tm-merchant-aside dd,.tm-merchant-review dd{margin:0;text-align:right}.tm-merchant-form-actions{display:flex;gap:10px;margin-top:20px}.tm-merchant-types{display:flex;flex-wrap:wrap;gap:18px;margin:0 0 18px;padding:15px;border:1px solid var(--tm-border);border-radius:10px}.tm-merchant-types legend{color:var(--tm-muted);font-size:12px}.tm-merchant-types label{display:flex;align-items:center;gap:7px;text-transform:capitalize}.tm-merchant-types input{accent-color:var(--tm-blue)}.tm-merchant-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px}.tm-merchant-metrics>div{min-height:130px;padding:24px}.tm-merchant-metrics span,.tm-merchant-metrics small{display:block;color:var(--tm-muted)}.tm-merchant-metrics strong{display:block;margin:12px 0;font-size:32px}.tm-merchant-dashboard{padding:24px;margin-bottom:24px}.tm-merchant-tools{display:flex;flex-wrap:wrap;gap:12px}.tm-merchant-toolbar{margin-bottom:16px}.tm-merchant-toolbar .tm-input{max-width:340px}.tm-merchant-workspace td small{display:block;color:var(--tm-muted)}
@media(max-width:1000px){.tm-merchant-columns{grid-template-columns:1fr}.tm-merchant-metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.tm-merchant-steps{overflow-x:auto;padding:16px;white-space:nowrap}.tm-merchant-form,.tm-merchant-aside,.tm-merchant-dashboard{padding:18px}.tm-merchant-metrics{gap:10px}.tm-merchant-metrics>div{padding:16px;min-height:110px}.tm-merchant-metrics strong{font-size:26px}.tm-merchant-toolbar{display:block}.tm-merchant-toolbar .tm-input{max-width:none;margin-top:12px}.tm-merchant-workspace .tm-tabs{flex-wrap:nowrap;overflow-x:auto}.tm-merchant-workspace .tm-tab{white-space:nowrap}}
</style>
